import{_ as e,c as s,o as n,aj as a}from"./chunks/framework.B-K7myP5.js";const b=JSON.parse('{"title":"可执行二进制文件","frontmatter":{"title":"可执行二进制文件","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/binaries.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/官方文章/binaries","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"},"next":{"text":"简介","link":"/docs/composer/教程/intro"}},"headers":[],"params":{"pkg":"composer/官方文章/binaries","sidebar":[{"text":"常见问题","items":[{"text":"如何为我的框架自定义一个扩展包安装目录？","link":"/docs/composer/index"},{"text":"如何使用脚本安装 Composer？","link":"/docs/composer/常见问题/to-install-composer-programmatically"},{"text":"使用 root 用户来安装扩展包是否安全？如何安全地安装未认证渠道的扩展包？","link":"/docs/composer/常见问题/to-install-untrusted-packages-safely"},{"text":"我应该将 vendor 目录加入版本控制吗？","link":"/docs/composer/常见问题/i-commit-the-dependencies-in-my-vendor-directory"},{"text":"Composer 使用的是什么版本命名规范？","link":"/docs/composer/常见问题/version-numbering-system-does-composer-itself-use"},{"text":"为什么限制版本是最佳实践？","link":"/docs/composer/常见问题/are-unbound-version-constraints-a-bad-idea"},{"text":"为何版本限制与对比符、通配符配合使用是个糟糕的行为？","link":"/docs/composer/常见问题/are-version-constraints-combining-comparisons-and-wildcards-a-bad-idea"},{"text":"为什么 Composer 不递归加载代码库？","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively"}]},{"text":"官方文章","items":[{"text":"分支别名","link":"/docs/composer/官方文章/aliases"},{"text":"版本限制","link":"/docs/composer/官方文章/versions"},{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"},{"text":"自定义安装器","link":"/docs/composer/官方文章/installers"},{"text":"使用 Satis 处理私有仓库","link":"/docs/composer/官方文章/private-packages-with-satis"},{"text":"HTTP 基础认证","link":"/docs/composer/官方文章/basic-authentication"},{"text":"创建 Composer 插件","link":"/docs/composer/官方文章/plugins"},{"text":"事件和自定义脚本","link":"/docs/composer/官方文章/scripts"},{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"},{"text":"可执行二进制文件","link":"/docs/composer/官方文章/binaries"}]},{"text":"教程","items":[{"text":"简介","link":"/docs/composer/教程/intro"},{"text":"基本使用","link":"/docs/composer/教程/basic-usage"},{"text":"创建扩展包","link":"/docs/composer/教程/libraries"},{"text":"Composer 命令的使用","link":"/docs/composer/教程/cli"},{"text":"json 完全解析","link":"/docs/composer/教程/schema"},{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"},{"text":"配置信息","link":"/docs/composer/教程/config"},{"text":"社区","link":"/docs/composer/教程/community"}]}],"versions":[]},"relativePath":"docs/composer/官方文章/binaries.md","filePath":"docs/[pkg].md"}'),i={name:"docs/composer/官方文章/binaries.md"};function t(r,o,c,p,d,l){return n(),s("div",null,[...o[0]||(o[0]=[a(`<h1 id="vendor-文件夹-和-vendor-bin-目录" tabindex="-1">Vendor 文件夹 和 <code>vendor/bin</code> 目录 <a class="header-anchor" href="#vendor-文件夹-和-vendor-bin-目录" aria-label="Permalink to “Vendor 文件夹 和 vendor/bin 目录”">​</a></h1><h2 id="vendor-文件是什么" tabindex="-1">vendor 文件是什么？ <a class="header-anchor" href="#vendor-文件是什么" aria-label="Permalink to “vendor 文件是什么？”">​</a></h2><p>任何一个 Composer 程序包想要传递给安装包的用户的命令行脚本都应该被列为 vendor 文件。</p><h2 id="如果包包含了包用户不需要的其他脚本-如构建或编译脚本-则代码不应被列为-vendor-文件。它是如何定义的" tabindex="-1">如果包包含了包用户不需要的其他脚本（如构建或编译脚本），则代码不应被列为 vendor 文件。 它是如何定义的？ <a class="header-anchor" href="#如果包包含了包用户不需要的其他脚本-如构建或编译脚本-则代码不应被列为-vendor-文件。它是如何定义的" aria-label="Permalink to “如果包包含了包用户不需要的其他脚本（如构建或编译脚本），则代码不应被列为 vendor 文件。它是如何定义的？”">​</a></h2><p>它是通过将 <code>bin</code> 键添加到项目中来定义的 <code>composer.json</code>。它被指定为文件数组，因此可以为任何给定项目添加多个二进制文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;bin&quot;: [&quot;bin/my-script&quot;, &quot;bin/my-other-script&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="在-composer-json-中定义供应商二进制文件有什么作用" tabindex="-1">在 composer.json 中定义供应商二进制文件有什么作用？ <a class="header-anchor" href="#在-composer-json-中定义供应商二进制文件有什么作用" aria-label="Permalink to “在 composer.json 中定义供应商二进制文件有什么作用？”">​</a></h2><p>它指示 Composer 将程序包的二进制文件安装到 <code>vendor/bin</code> 依赖于该项目的任何项目中。</p><p>这是一种公开有用脚本的便捷方式，否则这些脚本将隐藏在 <code>vendor/</code> 目录中。</p><h2 id="当-composer-在定义供应商二进制文件的-composer-json-上运行时会发生什么" tabindex="-1">当 Composer 在定义供应商二进制文件的 composer.json 上运行时会发生什么？ <a class="header-anchor" href="#当-composer-在定义供应商二进制文件的-composer-json-上运行时会发生什么" aria-label="Permalink to “当 Composer 在定义供应商二进制文件的 composer.json 上运行时会发生什么？”">​</a></h2><p>对于包直接定义的二进制文件，没有任何反应。</p><h2 id="当-composer-在与列出的供应商二进制文件有依赖关系的-composer-json-上运行时会发生什么" tabindex="-1">当 Composer 在与列出的供应商二进制文件有依赖关系的 composer.json 上运行时会发生什么？ <a class="header-anchor" href="#当-composer-在与列出的供应商二进制文件有依赖关系的-composer-json-上运行时会发生什么" aria-label="Permalink to “当 Composer 在与列出的供应商二进制文件有依赖关系的  composer.json 上运行时会发生什么？”">​</a></h2><p>Composer 查找所有依赖项中定义的二进制文件。从每个依赖项的二进制文件到 <code>vendor/bin</code> 创建符号链接。</p><p>假设包 <code>my-vendor/project-a</code> 有二进制文件设置如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;: &quot;my-vendor/project-a&quot;,</span></span>
<span class="line"><span>    &quot;bin&quot;: [&quot;bin/project-a-bin&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>为这个 <code>composer.json</code> 运行 <code>composer install</code> 不会对 <code>bin/project-a-bin</code> 做任何事情。</p><p>假设项目 <code>my-vendor/project-b</code> 的设置如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;name&quot;: &quot;my-vendor/project-b&quot;,</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;my-vendor/project-a&quot;: &quot;*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>为这个 <code>composer.json</code> 运行 <code>composer install</code> 将查看所有项目的二进制文件并将它们安装到 <code>vendor/bin</code>。</p><p>在这种情况下，Composer 将使 <code>vendor/my-vendor/project-a/bin/project-a-bin</code> 可用作 <code>vendor/bin/project-a-bin</code>。在类似 Unix 的平台上，这是通过创建符号链接来完成的。</p><h2 id="那么-windows-和-bat-文件呢" tabindex="-1">那么 Windows 和 .bat 文件呢? <a class="header-anchor" href="#那么-windows-和-bat-文件呢" aria-label="Permalink to “那么 Windows 和 .bat 文件呢?”">​</a></h2><p>完全由 Composer 管理的包不需要包含任何 <code>.bat</code> 文件以实现 Windows 兼容性。在 Windows 环境中运行时，Composer 以特殊的方式处理二进制文件的安装：</p><ul><li>自动生成 <code>.bat</code> 文件以引用二进制文件</li><li>将自动生成与二进制文件同名的 Unix 样式代理文件（对 Cygwin 或 Git Bash 很有用）</li></ul><p>我们欢迎需要支持但可能不包含 Composer 工作流的软件来维护自定义的 <code>.bat</code> 文件。在这种情况下，程序包不应该将 <code>.bat</code> 文件列为二进制文件，因为它不需要。</p><h2 id="是否可以将供应商二进制文件安装在-vendor-bin-以外的其他地方" tabindex="-1">是否可以将供应商二进制文件安装在 vendor/bin 以外的其他地方？ <a class="header-anchor" href="#是否可以将供应商二进制文件安装在-vendor-bin-以外的其他地方" aria-label="Permalink to “是否可以将供应商二进制文件安装在 vendor/bin 以外的其他地方？”">​</a></h2><p>是的，有两种方式可以指定备用供应商二进制的位置：</p><ol><li>在 <code>composer.json</code> 中设置 <code>bin-dir</code> 配置设置</li><li>设置环境变量 <code>COMPOSER_BIN_DIR</code></li></ol><p>前者的例子如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;config&quot;: {</span></span>
<span class="line"><span>        &quot;bin-dir&quot;: &quot;scripts&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>为 <code>composer.json</code> 运行 <code>composer install</code> 将导致所有供应商二进制文件都安装在 <code>scripts/</code> 而不是 <code>vendor/bin/</code> 中。</p><p>您可以将 <code>bin-dir</code> 设置为 <code>./</code> 以将二进制文件放入项目根目录中。</p>`,31)])])}const h=e(i,[["render",t]]);export{b as __pageData,h as default};
